SELECT pais_codigo, count(*) AS referencias
FROM public.precios_recursos_mercado
WHERE organizacion_id IS NULL
  AND activo IS TRUE
  AND pais_codigo = 'GB'
GROUP BY pais_codigo
ORDER BY pais_codigo;
